function markDirty(){if(!current()?.daily?.editable)return;let prior=draftCache[draftKey()];draftCache[draftKey()]={questions:$('questions').value,rounds:$('rounds').value,interval:$('interval').value,revision:prior?prior.revision:current().revision};dirty=true;plan();$('draftState').textContent='有未保存的修改；点击保存后立即应用';buttons()}
