 $('modelTitle').replaceChildren(modelLogo(m.id),node('span',m.name+' · 当前执行批次'));$('taskState').textContent=labels[c.state]||c.state;$('taskState').className='pill'+(['waiting_login','needs_attention','stale'].includes(c.state)?' warn':['paused','stopped','not_started'].includes(c.state)?' gray':'');$('batchId').textContent=c.batch;$('taskIssue').textContent=c.needs_review?'有 '+c.needs_review+' 题需要核对采集结果，系统不会自动重发。':'';$('taskIssue').className='notice error'+(c.needs_review?' show':'');
 const phaseNames={automatic_backoff:'自动退避，继续原任务',original_conversation_readback:'补读原会话，不重新提问',original_identity_backoff:'等待原会话身份恢复',awaiting_original_result:'等待原请求结果，自动复核',native_validation_backoff:'原生数据自动复核',infrastructure_backoff:'连接自动恢复中',preparation_backoff:'新会话准备重试',delivery_validation_backoff:'回执自动复核',starting:'准备启动',preparing:'检查新会话',sending_once:'提交本题一次',awaiting_ack:'等待原请求确认',generating:'模型正在生成',awaiting_complete_snapshot:'复核正文、全部信源与引用',verifying_complete_snapshot:'复核两次完成快照',rate_wait:'等待发送间隔',read_backoff:'原会话读取退避',delivery:'等待 GEO processed 回执',collecting:'网页采集／间隔等待'};
 const p=c.progress||{},diags=c.diagnostics||[];let detail=[phaseNames[p.phase]||labels[p.phase]||''];if(p.ordinal)detail.push('第 '+p.ordinal+' 题');if(p.next_at&&p.next_at>Date.now()/1000)detail.push('预计 '+time(p.next_at)+' 再检查');if(c.pending_delivery)detail.push(c.pending_delivery+' 条完整结果等待回执，暂不开始下一题');if(p.deadline_at&&['awaiting_ack','generating','awaiting_complete_snapshot'].includes(p.phase))detail.push('原请求限时复核至 '+time(p.deadline_at));
 const reasons={receiver_auth_required:'回传鉴权需处理；完整结果已保留',receiver_request_rejected:'回传参数被拒绝，需核对配置',receiver_invalid_response:'接收服务返回格式异常，完整结果已保留',receiver_rate_limited:'接收服务限流，按退避时间重试',receiver_unavailable:'接收服务暂不可用，自动退避',receiver_network_error:'回传网络异常，自动退避',receiver_processing_error:'接收端处理异常，保留原请求等待复核',result_or_receipt_invalid:'完整性或回执校验未通过，保留证据',awaiting_processed:'已排队，等待入库回执'};
 for(const d of diags){detail.push(reasons[d.code]||'回传状态待复核');if(d.next_at>Date.now()/1000)detail.push('下次检查 '+time(d.next_at))}if(c.nontext_observations)detail.push('原生视频回答 '+c.nontext_observations+' 次，审计回传 '+c.nontext_processed+'，不计正文成功');if(c.body_only_observations)detail.push('卡片正文完整 '+c.body_only_observations+' 次，已回传 '+c.body_only_processed+' 次；页面未公开引用，不计完整信源');if(c.updated_at)detail.push('心跳 '+time(c.updated_at));$('progressDetail').textContent=detail.filter(Boolean).join(' · ');
 $('captured').textContent=c.captured;$('planned').textContent='/ '+c.planned;$('processed').textContent=c.processed;$('unique').textContent=c.unique_processed;$('exceptions').textContent=c.duplicates+' / '+c.unavailable;$('exceptionLabel').textContent=m.id==='yuanbao'?'去重 / 仅视频回答':'去重 / 未取得完整结果';$('progressFill').style.width=Math.min(100,c.captured/Math.max(1,c.planned)*100)+'%';
 $('currentSettings').replaceChildren();for(let [a,b] of [['问题',c.config.questions.length+' 个'],['轮数',c.config.rounds+' 轮'],['间隔',m.backend==='android'&&m.id==='deepseek'?intervalLabel(m.id,c.config):'≥ '+c.config.interval+' 秒']]){let v=node('span');v.append(node('span',a+' '),node('b',b));$('currentSettings').append(v)}
 $('loginBox').hidden=!m.login;$('syncBtn').hidden=true;$('loginMessage').textContent=(m.login_status.account?m.login_status.account+' · ':'')+(['opening','waiting_login','verifying'].includes(m.manual_login?.status)?m.manual_login.message:m.login_status.message);$('loginTime').textContent=m.login_status.checked_at?time(m.login_status.checked_at):'尚未校验';
 const collecting=active(c.service_state)&&!['waiting_login','waiting_verification','needs_attention','stale'].includes(c.state);
 if(m.id==='deepseek'&&collecting)$('loginMessage').textContent='任务正在运行，采集器持续检查登录状态；无需重复登录或点击继续。';
 $('readinessChecks').replaceChildren();for(const check of m.readiness?.checks||[]){const neutral=collecting&&!check.ok&&['login','idle'].includes(check.name);const li=node('li',(neutral?'· ':check.ok?'✓ ':'○ ')+check.message);li.style.color=neutral?'#73847c':check.ok?'#19745e':'#9b623c';$('readinessChecks').append(li)}
